// Generates the Dashboard's view of the P1 `studio.local/v1` contract from the
// exported artefacts in `contracts/local/` (the single source of truth).
//
//   node scripts/gen-local-contracts.mjs           # (re)write the generated file
//   node scripts/gen-local-contracts.mjs --check   # fail if the file drifted
//
// The generated file carries three things derived mechanically from the export:
//   - the closed command table (allowlist.json),
//   - the JSON Schemas the Dashboard validates bridge messages against,
//   - TypeScript types produced from those very schemas.
// Nothing in `src/` restates a field, a command or a limit by hand.

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..", "..");
const localDir = resolve(root, "contracts", "local");
const outFile = resolve(here, "..", "src", "platform", "generated", "local-contracts.generated.ts");

/** Models the Dashboard consumes in P2 (envelopes + the served read-only commands). */
const MODELS = [
  "BridgeRequest",
  "BridgeResponse",
  "BridgeErrorMessage",
  "HandshakeRequest",
  "HandshakeResponse",
  "DaemonControlRequest",
  "DaemonControlResult",
  "DaemonStatus",
  "EmptyPayload",
  "IdentityView",
];

const readJson = (p) => JSON.parse(readFileSync(p, "utf8"));
const manifest = readJson(resolve(localDir, "manifest.json"));
const allowlist = readJson(resolve(localDir, "allowlist.json"));
const schemas = Object.fromEntries(
  MODELS.map((m) => [m, readJson(resolve(localDir, "schemas", `${m}.json`))]),
);

const hash = createHash("sha256");
hash.update(readFileSync(resolve(localDir, "manifest.json")));
hash.update(readFileSync(resolve(localDir, "allowlist.json")));
for (const m of MODELS) hash.update(readFileSync(resolve(localDir, "schemas", `${m}.json`)));
const digest = hash.digest("hex");

// ---------------------------------------------------------------- TS types --

const ident = (s) => (/^[A-Za-z_$][\w$]*$/.test(s) ? s : JSON.stringify(s));

function tsType(node) {
  if (node.$ref) return node.$ref.replace("#/$defs/", "");
  if (node.const !== undefined) return JSON.stringify(node.const);
  if (node.enum) return node.enum.map((v) => JSON.stringify(v)).join(" | ");
  if (node.anyOf) return node.anyOf.map(tsType).join(" | ");
  switch (node.type) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "array":
      return `${wrap(tsType(node.items ?? {}))}[]`;
    case "object": {
      if (node.properties) {
        const req = new Set(node.required ?? []);
        const lines = Object.entries(node.properties).map(
          ([k, v]) => `  ${ident(k)}${req.has(k) ? "" : "?"}: ${tsType(v)};`,
        );
        return `{\n${lines.join("\n")}\n}`;
      }
      const ap = node.additionalProperties;
      if (ap && typeof ap === "object") return `Record<string, ${tsType(ap)}>`;
      return "Record<string, unknown>";
    }
    default:
      throw new Error(`unsupported schema node: ${JSON.stringify(node).slice(0, 120)}`);
  }
}

const wrap = (t) => (/[|{]/.test(t) ? `(${t})` : t);

const named = new Map(); // type name -> schema node (defs, deduped, must agree)
for (const [model, schema] of Object.entries(schemas)) {
  for (const [name, def] of Object.entries(schema.$defs ?? {})) {
    const prev = named.get(name);
    if (prev && JSON.stringify(prev) !== JSON.stringify(def)) {
      throw new Error(`$defs/${name} differs between schemas (seen again in ${model})`);
    }
    named.set(name, def);
  }
  named.set(model, { ...schema, $defs: undefined });
}

const typeDecls = [...named.entries()]
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([name, node]) => {
    const body = tsType(node);
    const isObject = node.type === "object" && node.properties;
    return isObject
      ? `export interface ${name} ${body}`
      : `export type ${name} = ${body};`;
  });

// ------------------------------------------------------------------ output --

const commands = allowlist.commands
  .map((c) => ({
    command: c.command,
    mutating: c.mutating,
    capability: c.capability,
    request: c.request,
    response: c.response,
    max_request_bytes: c.max_request_bytes,
    max_response_bytes: c.max_response_bytes,
    timeout_ms: c.timeout_ms,
    cancellable: c.cancellable,
  }))
  .sort((a, b) => a.command.localeCompare(b.command));

const bundled = Object.fromEntries(
  Object.entries(schemas).map(([m, s]) => [m, s]),
);

const out = `// GENERATED by dashboard/scripts/gen-local-contracts.mjs — do not edit.
// Source: contracts/local/{manifest.json,allowlist.json,schemas/*.json} (P1, studio.local/v1).
// Regenerate: npm run gen:local-contracts   Drift check: npm run check:local-contracts

export const LOCAL_PROTOCOL = ${JSON.stringify(manifest.protocol)} as const;
export const LOCAL_SCHEMA_VERSION = ${JSON.stringify(manifest.schema_version)} as const;
export const LOCAL_CONTRACT_DIGEST = ${JSON.stringify(digest)} as const;

export interface LocalCommandSpec {
  readonly command: string;
  readonly mutating: boolean;
  readonly capability: string | null;
  readonly request: string;
  readonly response: string;
  readonly max_request_bytes: number;
  readonly max_response_bytes: number;
  readonly timeout_ms: number;
  readonly cancellable: boolean;
}

export const LOCAL_COMMANDS: readonly LocalCommandSpec[] = ${JSON.stringify(commands, null, 2)};

export const LOCAL_SCHEMAS: Readonly<Record<string, unknown>> = {
${Object.entries(bundled).map(([m, s]) => `  ${JSON.stringify(m)}: ${JSON.stringify(s)},`).join("\n")}
};

${typeDecls.join("\n\n")}
`;

if (process.argv.includes("--check")) {
  if (!existsSync(outFile) || readFileSync(outFile, "utf8") !== out) {
    console.error(
      "local-contracts.generated.ts is out of date with contracts/local/. Run: npm run gen:local-contracts",
    );
    process.exit(1);
  }
  console.log(`local contracts in sync (digest ${digest.slice(0, 12)})`);
} else {
  writeFileSync(outFile, out);
  console.log(`wrote ${outFile} (digest ${digest.slice(0, 12)})`);
}
